with open('data/data.json', 'r', encoding='utf-8') as f:
    data = json.load(f)

# 更新词根解释
updated_count = 0
for root in data['roots']:
    for word_obj in root['words']:
        word = word_obj['word'].lower()
        
        # 如果有准确的词根分解，更新它
        if word in accurate_etymologies:
            word_obj['etymology'] = accurate_etymologies[word]
            updated_count += 1

# 保存更新后的数据
with open('data/data.json', 'w', encoding='utf-8') as f:
    json.dump(data, f, ensure_ascii=False, indent=2)

print(f'已更新 {updated_count} 个单词的词根解释')

# 显示一些例子
print('\n更新后的例子：')
for root in data['roots'][1:6]:
    print(f'\n{root["name"]}:')
    for word in root['words'][:3]:
        if 'etymology' in word:
            print(f'  {word["word"]}: {word["etymology"]}')
